using System;using System.Globalization;using System.IO;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Controls;using System.Windows.Data;using System.Windows.Documents;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace FileCompass {
 internal static class HelpIllustrations {
  internal static BitmapSource Load(string id){if(!Regex.IsMatch(id??"",@"^[a-z0-9-]{1,40}$"))throw new ArgumentException("Invalid help illustration");string path=Path.Combine(HelpContent.Root,"images",HelpContent.ContentLanguage+"."+id+".png");using(var stream=File.OpenRead(path)){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=stream;bitmap.EndInit();bitmap.Freeze();return bitmap;}}
  internal static Block Figure(string id,FrameworkElement article,Window owner){var bitmap=Load(id);var image=new Image{Source=bitmap,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Left};image.SetBinding(FrameworkElement.WidthProperty,new Binding("ActualWidth"){Source=article,Converter=new FigureWidth(),Mode=BindingMode.OneWay});var button=new Button{Content=image,Padding=new Thickness(2),BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(1),Background=CompactTheme.WhiteSurface,HorizontalAlignment=HorizontalAlignment.Left,ToolTip=L.Text("help.zoom")};button.Click+=delegate{var viewer=new Window{Owner=owner,Title=L.Text("help.zoom"),Width=1100,Height=780,MinWidth=500,MinHeight=350,WindowStartupLocation=WindowStartupLocation.CenterOwner};FluentTheme.Dialog(viewer);ApplicationBrand.Attach(viewer);var panel=new DockPanel{Margin=new Thickness(12)};var zoom=new Slider{Minimum=40,Maximum=200,Value=100,Width=220,Margin=new Thickness(10)};var bar=new DockPanel();DockPanel.SetDock(bar,Dock.Top);panel.Children.Add(bar);bar.Children.Add(new TextBlock{Text=L.Text("help.zoom"),VerticalAlignment=VerticalAlignment.Center});bar.Children.Add(zoom);var full=new Image{Source=bitmap,Stretch=Stretch.None,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top};var scale=new ScaleTransform(1,1);full.LayoutTransform=scale;zoom.ValueChanged+=delegate{scale.ScaleX=scale.ScaleY=zoom.Value/100;};panel.Children.Add(new ScrollViewer{Content=full,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});viewer.Content=panel;DialogGeometry.Bound(viewer,1100,780,500,350);viewer.PreviewKeyDown+=delegate(object sender,System.Windows.Input.KeyEventArgs e){if(e.Key==System.Windows.Input.Key.Escape){e.Handled=true;viewer.Close();}};viewer.Show();};return new BlockUIContainer(button){Margin=new Thickness(0,8,0,8)};}
  sealed class FigureWidth:IValueConverter{public object Convert(object value,Type t,object parameter,CultureInfo c){return Math.Max(160,Math.Min(1000,System.Convert.ToDouble(value)-90));}public object ConvertBack(object v,Type t,object p,CultureInfo c){throw new NotSupportedException();}}
 }
}
